import java.io.BufferedReader
import java.io.InputStream
import java.io.InputStreamReader
import java.io.OutputStream
import java.io.PrintWriter
import kotlin.math.abs

fun insertDist(dist: Int, c: Char, distMap: MutableMap<Char, Int>, diff: Int) {
    if (dist <= 13 + diff) {
        distMap[c] = abs(dist - diff)
    } else {
        distMap[c] = 26 + diff - dist
    }
}

fun solve(input: InputStream, output: OutputStream) {
    val reader = BufferedReader(InputStreamReader(input))
    val out = PrintWriter(output, true)

    val distA = HashMap<Char, Int>()
    val distC = HashMap<Char, Int>()
    val distT = HashMap<Char, Int>()
    val distG = HashMap<Char, Int>()

    val alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    for ((i, c) in alphabet.withIndex()) {
        val dist = i
        insertDist(dist, c, distA, 0)
        insertDist(dist, c, distC, 2)
        if (dist <= 6) {
            distT[c] = 7 + dist
        } else {
            distT[c] = abs(dist - 19)
        }
        insertDist(dist, c, distG, 6)
    }

    val nLine = reader.readLine()
    val n = nLine.trim().toInt()

    val sLine = reader.readLine()
    val s = sLine.trim()
    val charVec = s.toCharArray()

    var minSum = -1
    for (i in 0 until n - 3) {
        val sum =
            distA[charVec[i]]!! +
            distC[charVec[i + 1]]!! +
            distT[charVec[i + 2]]!! +
            distG[charVec[i + 3]]!!

        if (minSum == -1 || sum < minSum) {
            minSum = sum
        }
    }

    out.println(minSum)
}

fun main() {
    solve(System.`in`, System.out)
}

